#include <set>
#include <vector>
#include <algorithm>

int main() {
    std::set<int> s = {10, 20, 50};

    // 1. O(log N) insertion (no useful hint)
    s.insert(15); 

    // 2. O(1) amortized insertion (good hint)
    // We know 30 comes after 20.
    auto it = s.find(20);
    s.insert(++it, 30); // Use hint right after 20

    // 3. O(N) bulk insertion using correct hints
    std::vector<int> data = {60, 70, 80};
    auto hint = s.end(); 
    for (int val : data) {
        // Subsequent hint is the end() iterator, which is O(1) here
        hint = s.insert(hint, val);
    }
}
